using StardewModdingAPI;\nusing StardewModdingAPI.Events;\nusing StardewValley;\n\nnamespace EnhancedSchoolsMod\n{\n    public class ModEntry : Mod\n    {\n        private ModConfig Config = null!;\n        private DataManager DataManager = null!;\n        private SchoolManager SchoolManager = null!;\n        private TermHandler TermHandler = null!;\n        private CalendarHandler CalendarHandler = null!;\n        private SchoolEventHandler SchoolEventHandler = null!;\n\n        public override void Entry(IModHelper helper)\n        {\n            Config = helper.ReadConfig<ModConfig>();\n            this.Monitor.Log($\"Config loaded with {Config.HolidaySchedule.Count} holidays.\", LogLevel.Info);\n\n            DataManager = new DataManager(helper, this.Monitor);\n            SchoolManager = new SchoolManager(Config, this.Monitor);\n            TermHandler = new TermHandler(Config, this.Monitor);\n            CalendarHandler = new CalendarHandler(helper, DataManager, SchoolManager, this.Monitor);\n            SchoolEventHandler = new SchoolEventHandler(DataManager, SchoolManager, TermHandler, this.Monitor);\n\n            RegisterEventHandlers(helper);\n            this.Monitor.Log(\"Enhanced Schools Mod loaded successfully!\", LogLevel.Info);\n        }\n\n        private void RegisterEventHandlers(IModHelper helper)\n        {\n            helper.Events.GameLoop.GameLaunched += OnGameLaunched;\n            helper.Events.GameLoop.SaveLoaded += OnSaveLoaded;\n            helper.Events.GameLoop.DayStarted += OnDayStarted;\n            helper.Events.GameLoop.DayEnding += OnDayEnding;\n            helper.Events.GameLoop.Saved += OnSaved;\n            helper.Events.Display.MenuChanged += OnMenuChanged;\n        }\n\n        private void OnGameLaunched(object? sender, GameLaunchedEventArgs e) { }\n        private void OnSaveLoaded(object? sender, SaveLoadedEventArgs e) => DataManager.LoadChildSchoolData();\n        private void OnDayStarted(object? sender, DayStartedEventArgs e) => SchoolEventHandler.HandleDayStart();\n        private void OnDayEnding(object? sender, DayEndingEventArgs e) => SchoolEventHandler.HandleDayEnd();\n        private void OnSaved(object? sender, SavedEventArgs e) => DataManager.SaveChildSchoolData();\n        private void OnMenuChanged(object? sender, MenuChangedEventArgs e) => CalendarHandler.HandleMenuChanged(e.NewMenu);\n    }\n}